ROOT=Path(__file__).resolve().parents[2];REPO=ROOT.parents[1]
script="""import {pengajarHarness,plain} from './apps-script/absensi-dashboard/tests/support/pengajar-harness.mjs';const h=pengajarHarness(),t=h.t;const f={html:{},roles:{},tokens:{},responses:{},storageKey:h.teacher.storage_key};for(const n of ['Index','Beranda','Pengelolaan','Peserta','Profil','ManajemenAkses'])f.html[n]=t.c.keluaranAplikasiPanitia_(n,n).content;for(const [role,user] of Object.entries({teacher:h.teacher,admin:h.admin})){f.roles[role]=t.c.muatSesiAplikasiPanitia(user.token);f.tokens[role]=user.token;const call=(n,...a)=>h.call(user,n,...a);f.responses[role]={muatAwalIndex:call('muatAwalIndex'),muatBerandaIndex:call('muatBerandaIndex'),muatKehadiranIndex:call('muatKehadiranIndex','SES001'),muatDaftarIzinIndex:call('muatDaftarIzinIndex','SES001'),muatCatatanPerilakuIndex:call('muatCatatanPerilakuIndex','SES001'),muatRekapJPProgramIndex:call('muatRekapJPProgramIndex','PRG001'),muatNilaiPerilakuProgramIndex:call('muatNilaiPerilakuProgramIndex','PRG001'),muatPesertaProgramIndex:call('muatPesertaProgramIndex','PRG001','',0),muatProfilPesertaIndex:call('muatProfilPesertaIndex',{id_peserta:'PST001'}),muatEvaluasiPesertaSesi:call('muatEvaluasiPesertaSesi','SES001')};}for(const [n,a] of [['muatKelolaProgramIndex',['PRG001']],['muatManajemenAksesPanitia',[]],['muatMasterPesertaHapusIndex',[]],['muatKelolaPengajar',[]]])f.responses.admin[n]=h.call(h.admin,n,...a);f.flow=t.startApp();f.saved=h.call(h.teacher,'simpanEvaluasiPesertaSesi',h.payload());f.after={teacher:h.call(h.teacher,'muatEvaluasiPesertaSesi','SES001'),admin:h.call(h.admin,'muatEvaluasiPesertaSesi','SES001')};process.stdout.write(JSON.stringify(plain(f)));"""
f=json.loads(subprocess.check_output(['node','--input-type=module','-e',script],cwd=REPO,text=True))
MOCK=r'''
window.__f=FIXTURE;window.__role='teacher';window.__calls=[];window.__graded=false;window.__failSave=false;window.__expired=false;window.__bulk=false;window.__saveCount=0;window.__loseSecond=false;
function response(name,arg){const f=window.__f,role=window.__role;if(name==='muatSesiAplikasiPanitia')return f.roles[role];if(name==='mulaiLoginAplikasiPanitia')return f.flow;if(name==='keluarAplikasiPanitia')return {sukses:true};if(name!=='panggilAplikasiPanitia')throw Error('Unexpected native '+name);const n=arg.nama,a=arg.args;if(window.__expired||arg.token!==f.tokens[role])throw Error('SESI_BERAKHIR');
 if(n==='muatEvaluasiPesertaSesi')return window.__graded?f.after[role]:f.responses[role][n];
 if(n==='simpanEvaluasiPesertaSesi'){if(window.__failSave)throw Error('Respons terputus');window.__saveCount++;if(window.__bulk){if(!window.__graded)f.after.teacher=JSON.parse(JSON.stringify(f.responses.teacher.muatEvaluasiPesertaSesi));for(const item of a[0].nilai){const p=f.after.teacher.peserta.find(p=>p.id_keikutsertaan===item.id_keikutsertaan);p.penilaian={skor:item.skor,catatan:item.catatan,versi:a[0].id_permintaan,versi_sumber:a[0].versi_sumber,waktu:new Date().toISOString()};}}window.__graded=true;if(window.__bulk&&window.__loseSecond&&window.__saveCount===2)throw Error('Respons paket kedua terputus');return f.saved;}
 if(n==='tetapkanPengajarSesi'){const d=a[0],r=f.responses.admin.muatKelolaPengajar.penugasan.find(x=>x.id_sesi===d.id_sesi);r.id_pengajar=d.id_pengajar;r.status=d.id_pengajar?'aktif':'nonaktif';return {sukses:true,pesan:'Penugasan tersimpan.'};}
 if(n==='muatDaftarVerifikasiSesiPanitia'||n==='muatPengajuanKoreksiPanitia')return {sukses:true,pengajuan:[]};
 if(n==='muatPenghapusanTertundaIndex')return {sukses:true,transaksi:[],transaksi_lain:[]};
 const r=f.responses[role][n];if(r)return JSON.parse(JSON.stringify(r));throw Error('Unexpected '+n);
}
function bridge(ok,bad){return new Proxy({}, {get(t,n){if(n==='withSuccessHandler')return f=>bridge(f,bad);if(n==='withFailureHandler')return f=>bridge(ok,f);return arg=>{window.__calls.push({name:n,arg});setTimeout(()=>{try{ok?.(response(n,arg));}catch(e){bad?.(e);}},20);};}});}
window.google={script:{run:bridge(),host:{close(){}},url:{getLocation(fn){fn({parameter:Object.fromEntries(new URL(location.href).searchParams)});}}}};
'''.replace('FIXTURE',json.dumps(f))
out=Path(os.environ.get('PENGAJAR_SCREENSHOT_DIR','/tmp/pengajar-ui-preview'));out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 def open_page(file='Index',role='teacher',width=1440,init=''):
  page=browser.new_page(viewport={'width':width,'height':1050});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.add_init_script(MOCK+'window.__role='+json.dumps(role)+';sessionStorage.setItem(window.__f.storageKey,window.__f.tokens[window.__role]);'+init)
  def route(r):
   if r.request.resource_type!='document':r.abort();return
   u=urlparse(r.request.url);name={'monitoring':'Index','pengelolaan':'Pengelolaan','peserta':'Peserta','profil':'Profil','akses':'ManajemenAkses'}.get(parse_qs(u.query).get('page',[''])[0],file)
   if u.path!='/macros/s/COPY/exec':r.fulfill(status=404,body='Not found');return
   r.fulfill(status=200,content_type='text/html',body=f['html'][name])
  page.route('**/*',route);q={'Index':'monitoring','Pengelolaan':'pengelolaan','ManajemenAkses':'akses'}.get(file,'beranda');page.goto('https://script.google.com/macros/s/COPY/exec?page='+q+'&program=PRG001&jenjang=JEN001&sesi=SES001');return page,errors
 for width in [1440,390]:
  page,errors=open_page(width=width);expect(page.locator('.sidebar-account-text small')).to_have_text('Pengajar');expect(page.locator('#total')).to_have_text('1');expect(page.locator('[data-dash-page="pengelolaan"]')).not_to_be_visible();expect(page.locator('#openQR')).not_to_be_visible();assert page.locator('#panitiaVerification').count()==0;assert page.locator('#sesi option').count()==2;assert 'SECRET' not in page.locator('body').inner_text()
  page.locator('#openEvaluasiPeserta').click();expect(page.locator('#evaluasiPesertaDialog')).to_be_visible();expect(page.locator('#evaluasiPesertaDialog select')).to_have_count(6);expect(page.locator('#evaluasiPesertaDialog')).to_contain_text('Belum dinilai');page.locator('#evaluasiPesertaDialog select').nth(0).select_option('4');page.locator('#saveEvaluasiPeserta').click();expect(page.locator('#evaluasiPesertaStatus')).to_contain_text('Lengkapi enam aspek');assert not page.evaluate("window.__calls.some(c=>c.arg?.nama==='simpanEvaluasiPesertaSesi')")
  for i,n in enumerate([4,5,4,5,3,4]):page.locator('#evaluasiPesertaDialog select').nth(i).select_option(str(n))
  page.locator('#evaluasiPesertaDialog textarea').fill('Berpartisipasi dalam diskusi');page.locator('#saveEvaluasiPeserta').click();expect(page.locator('#evaluasiPesertaStatus')).to_contain_text('tersimpan');expect(page.locator('#evaluasiPesertaDialog')).to_contain_text('Tersimpan');assert page.evaluate("window.__calls.some(c=>c.arg?.nama==='simpanEvaluasiPesertaSesi'&&Object.keys(c.arg.args[0].nilai[0].skor).length===6)");assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path=str(out/('Evaluasi-Peserta-'+str(width)+'.png')));assert not errors,errors;page.close()
 bulk_init="window.__bulk=true;window.__loseSecond=true;const base=window.__f.responses.teacher.muatEvaluasiPesertaSesi.peserta[0];window.__f.responses.teacher.muatEvaluasiPesertaSesi.peserta=Array.from({length:20},(_,i)=>({...JSON.parse(JSON.stringify(base)),id_keikutsertaan:'KST_BULK_'+i,nama:'Peserta '+i,penilaian:null}));"
 bulk,ber=open_page(init=bulk_init);expect(bulk.locator('#sesi')).to_have_value('SES001');bulk.locator('#openEvaluasiPeserta').click();expect(bulk.locator('#evaluasiPesertaDialog select')).to_have_count(120)
 for i in range(120):bulk.locator('#evaluasiPesertaDialog select').nth(i).select_option('4')
 bulk.locator('#saveEvaluasiPeserta').click();expect(bulk.locator('#evaluasiPesertaStatus')).to_contain_text('paket kedua terputus');expect(bulk.locator('#evaluasiPesertaDialog select').first).to_be_disabled();calls=bulk.evaluate("window.__calls.filter(c=>c.arg?.nama==='simpanEvaluasiPesertaSesi').map(c=>c.arg.args[0])");assert len(calls)==2;assert all(len(c['nilai'])==10 for c in calls);bulk.locator('#saveEvaluasiPeserta').click();expect(bulk.locator('#evaluasiPesertaStatus')).to_contain_text('20 penilaian peserta tersimpan');again=bulk.evaluate("window.__calls.filter(c=>c.arg?.nama==='simpanEvaluasiPesertaSesi').map(c=>c.arg.args[0])");assert again[1]==again[2];assert not ber,ber;bulk.close()
 expired,ere=open_page();expect(expired.locator('#sesi')).to_have_value('SES001');expired.locator('#openEvaluasiPeserta').click();expect(expired.locator('#evaluasiPesertaDialog select')).to_have_count(6)
 for i in range(6):expired.locator('#evaluasiPesertaDialog select').nth(i).select_option('4')
 expired.evaluate('window.__expired=true');expired.locator('#saveEvaluasiPeserta').click();expect(expired.locator('#panitiaAuth')).to_be_visible();expect(expired.locator('#evaluasiPesertaDialog')).not_to_be_visible();assert not ere,ere;expired.close()
 admin,ae=open_page(role='admin');expect(admin.locator('#sesi')).to_have_value('SES001');admin.locator('#openEvaluasiPeserta').click();expect(admin.locator('#evaluasiPesertaDialog')).to_be_visible();expect(admin.locator('#saveEvaluasiPeserta')).not_to_be_visible();assert admin.locator('#evaluasiPesertaDialog select').count()==0;admin.screenshot(path=str(out/'Evaluasi-Admin.png'));assert not ae,ae
 manage,me=open_page('Pengelolaan',role='admin');expect(manage.locator('#kelolaPengajarSesi')).to_be_visible();expect(manage.locator('#sessionTeacher option')).to_have_count(3);manage.locator('#pengajarSesiTarget').select_option('SES001');expect(manage.locator('#pengajarSesiUser')).to_have_value(f['after']['admin']['id_pengajar']);manage.locator('#pengajarSesiUser').select_option('');manage.locator('#pengajarSesiReason').fill('Pengajar diganti pada jadwal berikutnya');manage.locator('#savePengajarSesi').click();manage.wait_for_function("window.__calls.some(c=>c.arg?.nama==='tetapkanPengajarSesi')");assert not me,me
 access,ace=open_page('ManajemenAkses',role='admin');expect(access.locator('#userRole option[value="pengajar"]')).to_have_text('Pengajar');assert not ace,ace
 blocked,be=open_page('Pengelolaan');expect(blocked.locator('#panitiaAuth')).to_be_visible();expect(blocked.locator('#panitiaAuthMessage')).to_contain_text('Admin');assert not blocked.evaluate("window.__calls.some(c=>c.name==='panggilAplikasiPanitia')");assert not be,be
 browser.close()
